-- Mould Job Tracker: Supabase schema
-- Generated by node scripts/build-schema.mjs from the versioned migrations.
-- Raw material received through mould completion; no purchasing tables.
-- FRESH SUPABASE PROJECTS ONLY. Existing installations must use pending migrations.
-- Requires Supabase Auth/Storage schemas and the anon/authenticated roles.
-- Run the entire file as the database owner in SQL Editor, not as the anon key.
-- This installer does not register migration history. Prefer the migration workflow
-- when you intend to manage the deployment with Supabase CLI/Management API.
-- No users, PINs, API keys, drawings, or operational/customer data are included.

begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';

do $preflight$
begin
 if to_regclass('auth.users') is null or to_regclass('storage.objects') is null or to_regclass('storage.buckets') is null then
  raise exception 'This schema requires a Supabase project with Auth and Storage installed.';
 end if;
 if exists(select 1 from pg_tables where schemaname='public')
  or exists(select 1 from pg_namespace where nspname='app_private')
  or exists(select 1 from pg_type t join pg_namespace n on n.oid=t.typnamespace where n.nspname='public' and t.typname in ('app_role','category','step_status')) then
  raise exception 'This project already contains a schema. Do not rerun the installer; apply only pending versioned migrations.';
 end if;
end
$preflight$;

-- Source: 20261103124452_foundation.sql
-- Phase 1: all operational data is retained; deletion is blocked even for privileged API clients.
create extension if not exists pgcrypto;
create type public.app_role as enum ('developer','admin','operator','viewer');
create type public.category as enum ('base','child','turn','hardware');
create type public.step_status as enum ('PENDING','IN PROCESS','DONE','DELAY','NOT APPLICABLE');
create table public.users (id uuid primary key references auth.users(id), name text not null, phone text, role public.app_role not null default 'viewer', language text not null default 'en' check (language in ('en','hi','mr')), active boolean not null default true, hidden boolean generated always as (role = 'developer') stored, archived_at timestamptz, created_at timestamptz not null default now());
create table public.customers (id uuid primary key default gen_random_uuid(), name text not null, code text, archived_at timestamptz);
create table public.jobs (id uuid primary key default gen_random_uuid(), customer_id uuid references public.customers, mould_code text not null unique, name text not null, qr_code text, trial_date_t0 date, status text not null default 'active' check(status in ('active','on_hold','finished','archived')), priority text not null default 'normal' check(priority in ('normal','high','urgent')), created_by uuid references public.users, archived_at timestamptz);
create table public.job_date_history (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs, field text not null, old_value text, new_value text, reason text not null, changed_by uuid references public.users, at timestamptz not null default now(), archived_at timestamptz);
create table public.bom_sheets (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs, section public.category not null, title text, prepared_by text, review_by text, checked_by text, order_by text, received_by text, sheet_date text, source_image text, revision_no integer not null default 1, archived_at timestamptz);
create table public.bom_revisions (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs, revision_no integer not null, snapshot jsonb not null, reason text, created_by uuid references public.users, at timestamptz not null default now(), archived_at timestamptz, unique(job_id,revision_no));
create table public.bom_items (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs, category public.category not null, serial_no integer, name text not null, material text, finish_size_text text, rough_size_text text, finish_dims jsonb, rough_dims jsonb, size_text text, remark text, used_with_item_id uuid references public.bom_items, qty_required numeric not null check(qty_required > 0), drawing_ref text, two_d_submitted boolean not null default false, notes text, archived_at timestamptz);
create table public.step_templates (id uuid primary key default gen_random_uuid(), category public.category not null, step_name text not null, order_no integer not null, default_days integer check(default_days >= 0), active boolean not null default true, archived_at timestamptz);
create table public.material_routes (id uuid primary key default gen_random_uuid(), material text not null, step_name text not null, order_no integer not null, archived_at timestamptz);
create table public.vendors (id uuid primary key default gen_random_uuid(), name text not null, contact text, type text, archived_at timestamptz);
create table public.dispatch_batches (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.jobs, label text, mode text not null check(mode in ('inhouse','outsourced')), sent_on date, created_by uuid references public.users, notes text, archived_at timestamptz);
create table public.batch_items (id uuid primary key default gen_random_uuid(), batch_id uuid not null references public.dispatch_batches, bom_item_id uuid not null references public.bom_items, qty_sent numeric not null check(qty_sent > 0), qty_back numeric not null default 0 check(qty_back >= 0 and qty_back <= qty_sent), archived_at timestamptz);
create table public.part_steps (id uuid primary key default gen_random_uuid(), bom_item_id uuid not null references public.bom_items, batch_id uuid references public.dispatch_batches, step_name text not null, status public.step_status not null default 'PENDING', mode text check(mode in ('inhouse','outsourced')), vendor_id uuid references public.vendors, planned_date date, started_on date, done_on date, target_date date, archived_at timestamptz);
create table public.receiving_checks (id uuid primary key default gen_random_uuid(), bom_item_id uuid not null references public.bom_items, qty_expected numeric not null, qty_found numeric not null check(qty_found >= 0), result text not null check(result in ('ok','short','excess','wrong')), checked_by uuid references public.users, checked_on timestamptz not null default now(), archived_at timestamptz);
create table public.movements (id uuid primary key default gen_random_uuid(), bom_item_id uuid not null references public.bom_items, "from" text, "to" text, qty numeric not null check(qty > 0), dispatched_on date, returned_on date, archived_at timestamptz);
create table public.remarks (id uuid primary key default gen_random_uuid(), entity_type text not null, entity_id uuid not null, text text not null, kind text not null check(kind in ('manual','alert','delay','info')), created_at timestamptz not null default now(), created_by uuid references public.users, archived_at timestamptz);
create table public.holidays (id uuid primary key default gen_random_uuid(), date date not null unique, note text, archived_at timestamptz);
create table public.settings (key text primary key, value jsonb not null, archived_at timestamptz);
create table public.user_prefs (user_id uuid primary key references public.users, language text not null default 'en' check(language in ('en','hi','mr')), archived_at timestamptz);
create table public.developer_credentials (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.users, device_name text not null, public_key text not null, registered_on timestamptz not null default now(), archived_at timestamptz);
create table public.kill_requests (id uuid primary key default gen_random_uuid(), requested_by uuid not null references public.users, scheduled_for timestamptz, status text not null check(status in ('scheduled','cancelled','done')), created_at timestamptz not null default now(), archived_at timestamptz);
create table public.audit_log (id bigint generated always as identity primary key, user_id uuid, table_name text not null, row_id text not null, action text not null, old_value jsonb, new_value jsonb, at timestamptz not null default now(), archived_at timestamptz);

create function public.current_app_role() returns public.app_role language sql stable security definer set search_path = public as $$ select role from public.users where id = auth.uid() and active and archived_at is null $$;
revoke all on function public.current_app_role() from public; grant execute on function public.current_app_role() to authenticated;
create function public.audit_change() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.audit_log(user_id,table_name,row_id,action,old_value,new_value) values (auth.uid(),tg_table_name,coalesce(to_jsonb(new)->>'id',to_jsonb(new)->>'key',to_jsonb(new)->>'user_id',to_jsonb(old)->>'id'),tg_op,case when tg_op='INSERT' then null else to_jsonb(old) end,case when tg_op='DELETE' then null else to_jsonb(new) end); return coalesce(new,old); end $$;
create function public.no_delete() returns trigger language plpgsql as $$ begin raise exception 'Hard delete is disabled; archive the record instead'; end $$;
create function public.append_only() returns trigger language plpgsql as $$ begin raise exception 'History is append-only'; end $$;
-- Audit all changes, including administrative writes; audit records themselves cannot be modified.
do $$ declare t text; begin foreach t in array array['users','customers','jobs','job_date_history','bom_sheets','bom_revisions','bom_items','step_templates','material_routes','dispatch_batches','batch_items','part_steps','vendors','receiving_checks','movements','remarks','holidays','settings','user_prefs','developer_credentials','kill_requests'] loop execute format('create trigger audit_changes after insert or update or delete on public.%I for each row execute function public.audit_change()',t); execute format('create trigger prevent_delete before delete on public.%I for each row execute function public.no_delete()',t); execute format('alter table public.%I enable row level security',t); end loop; end $$;
alter table public.audit_log enable row level security;
create trigger audit_immutable before update or delete on public.audit_log for each row execute function public.append_only();
create trigger remarks_immutable before update or delete on public.remarks for each row execute function public.append_only();
create trigger revisions_immutable before update or delete on public.bom_revisions for each row execute function public.append_only();
create trigger dates_immutable before update or delete on public.job_date_history for each row execute function public.append_only();
-- Operational tables: all active roles read; operators and above write. No DELETE policies.
do $$ declare t text; begin foreach t in array array['customers','jobs','bom_sheets','bom_items','dispatch_batches','batch_items','part_steps','vendors','receiving_checks','movements'] loop execute format('create policy read_active on public.%I for select to authenticated using (public.current_app_role() is not null)',t); execute format('create policy write_operational on public.%I for insert to authenticated with check (public.current_app_role() in (''developer'',''admin'',''operator''))',t); execute format('create policy update_operational on public.%I for update to authenticated using (public.current_app_role() in (''developer'',''admin'',''operator'')) with check (public.current_app_role() in (''developer'',''admin'',''operator''))',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['step_templates','material_routes','holidays','settings'] loop execute format('create policy read_settings on public.%I for select to authenticated using (public.current_app_role() is not null)',t); execute format('create policy insert_settings on public.%I for insert to authenticated with check (public.current_app_role() in (''developer'',''admin''))',t); execute format('create policy update_settings on public.%I for update to authenticated using (public.current_app_role() in (''developer'',''admin'')) with check (public.current_app_role() in (''developer'',''admin''))',t); end loop; end $$;
do $$ declare t text; begin foreach t in array array['remarks','bom_revisions','job_date_history'] loop execute format('create policy read_history on public.%I for select to authenticated using (public.current_app_role() is not null)',t); execute format('create policy add_history on public.%I for insert to authenticated with check (public.current_app_role() in (''developer'',''admin'',''operator''))',t); end loop; end $$;
create policy read_users on public.users for select to authenticated using (public.current_app_role() = 'developer' or (public.current_app_role() = 'admin' and role <> 'developer') or (id = auth.uid() and public.current_app_role() is not null));
create policy add_users on public.users for insert to authenticated with check (public.current_app_role() = 'developer' or (public.current_app_role() = 'admin' and role in ('operator','viewer')));
create policy update_users on public.users for update to authenticated using (public.current_app_role() = 'developer' or (public.current_app_role() = 'admin' and role in ('operator','viewer'))) with check (public.current_app_role() = 'developer' or (public.current_app_role() = 'admin' and role in ('operator','viewer')));
create policy own_prefs_read on public.user_prefs for select to authenticated using (user_id=auth.uid() and public.current_app_role() is not null);
create policy own_prefs_insert on public.user_prefs for insert to authenticated with check (user_id=auth.uid() and public.current_app_role() is not null);
create policy own_prefs_update on public.user_prefs for update to authenticated using (user_id=auth.uid() and public.current_app_role() is not null) with check (user_id=auth.uid() and public.current_app_role() is not null);
create policy developer_credentials_only on public.developer_credentials for all to authenticated using (public.current_app_role()='developer' and user_id=auth.uid()) with check (public.current_app_role()='developer' and user_id=auth.uid());
create policy developer_kill_read on public.kill_requests for select to authenticated using (public.current_app_role()='developer');
-- Kill requests have no client write policy until the separately secured kill-switch phase.
create policy developer_audit_read on public.audit_log for select to authenticated using (public.current_app_role()='developer');
create view public.readiness with (security_invoker=true) as select j.id as job_id, count(i.id) filter (where exists (select 1 from public.part_steps s where s.bom_item_id=i.id and s.archived_at is null and s.status <> 'NOT APPLICABLE')) as parts_total, count(i.id) filter (where exists (select 1 from public.part_steps s where s.bom_item_id=i.id and s.archived_at is null and s.status <> 'NOT APPLICABLE') and not exists (select 1 from public.part_steps s where s.bom_item_id=i.id and s.archived_at is null and s.status not in ('DONE','NOT APPLICABLE'))) as parts_ready from public.jobs j left join public.bom_items i on i.job_id=j.id and i.archived_at is null where j.archived_at is null group by j.id;
create view public.criticality with (security_invoker=true) as select r.*, j.trial_date_t0, case when r.parts_total=0 then null else r.parts_ready::numeric/r.parts_total end as readiness from public.readiness r join public.jobs j on j.id=r.job_id;
